def transform(grid):
    # Treat 3/9 connected clusters as separate symbols. Remove the cluster
    # whose 9-mark arrangement is a paired duplicate of its 3x3 counterpart.
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    x,y=q.pop(); cells.append((x,y))
                    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=a<h and 0<=b<w and g[a][b] and (a,b) not in seen:
                            seen.add((a,b));q.append((a,b))
                comps.append(cells)
    # From demonstration: the abnormal object is the connected component with
    # four marks in a symmetric two-by-two pattern; erase that component.
    for cells in comps:
        marks=[(r,c) for r,c in cells if g[r][c]==9]
        if len(marks)==4:
            rs=sorted({r for r,c in marks}); cs=sorted({c for r,c in marks})
            if len(rs)==2 and len(cs)==2 and set(marks)=={(r,c) for r in rs for c in cs}:
                for r,c in cells:g[r][c]=0
                break
    return g
